bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -w /opt/videobot "$cid" node --input-type=module -e '
import {readFileSync} from "node:fs";
const files=["src/telegram/freeAlbum.mjs","src/telegram/paidMedia.mjs","src/telegram/paidListingPublisher.mjs"];
for(const file of files){const s=readFileSync("/opt/videobot/"+file,"utf8");
 const checks=file.includes("freeAlbum")?["sendMediaGroup","has_spoiler: true","type: 'photo'","type: 'video'"]:file.includes("paidMedia")?["star_count","type:'video'"]:["sendMediaGroup","sendPaidMedia","media_group_id","paid_media"];
 console.log(file+"="+checks.map(v=>s.includes(v)?"1":"0").join(""));
}
'
